import { useCallback, useEffect, useState } from "react";
import { Link } from "@tanstack/react-router";
import { AlertTriangle, Box, PackagePlus, type LucideIcon } from "lucide-react";
import { VendorNotice, VendorPageHeading } from "@/components/vendor/vendor-shell";
import { changeVendorStock, editVendorListing, loadVendorInventory } from "@/lib/api/vendor";
import { formatINR } from "@/lib/money";
import type { VendorInventoryItem } from "@/lib/server/vendor";
export function InventoryTable({ lowStock = false }: { lowStock?: boolean }) {
  const [products, setProducts] = useState<VendorInventoryItem[]>([]); const [error, setError] = useState(""); const [busy, setBusy] = useState<string | null>(null);
  const refresh = useCallback(async () => { const r = await loadVendorInventory({ data: { lowStock } }); if (r.success) { setProducts(r.products); setError(""); } else setError(r.message); }, [lowStock]);
  useEffect(() => { void refresh(); }, [refresh]);
  async function stock(id: string, quantityChange: number) { setBusy(id); const result = await changeVendorStock({ data: { listingId: id, quantityChange } }); setBusy(null); if (result.success) await refresh(); else setError(result.message); }
  async function toggle(item: VendorInventoryItem) { setBusy(item.id); const result = await editVendorListing({ data: { listingId: item.id, enabled: !item.enabled } }); setBusy(null); if (result.success) await refresh(); else setError(result.message); }
  const totals = { all: products.length, in: products.filter((p) => p.enabled && p.available_quantity > 0 && p.available_quantity > p.minimum_stock).length, low: products.filter((p) => p.enabled && p.available_quantity > 0 && p.available_quantity <= p.minimum_stock).length, empty: products.filter((p) => p.enabled && p.available_quantity === 0).length };
  return <><VendorPageHeading eyebrow="Inventory" title={lowStock ? "Low stock products" : "Inventory management"} description="Manage your shop listings and stock. Global product details are controlled by PrintHub Admin." action={!lowStock && <Link to="/vendor/inventory/add" className="btn-primary"><PackagePlus className="size-4" />Add product to shop</Link>} />{error && <VendorNotice tone="warning">{error}</VendorNotice>}{!lowStock && <><div className="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{([{ label: "Total products", value: totals.all, icon: Box }, { label: "In stock", value: totals.in, icon: Box }, { label: "Low stock", value: totals.low, icon: AlertTriangle }, { label: "Out of stock", value: totals.empty, icon: AlertTriangle }] satisfies { label: string; value: number; icon: LucideIcon }[]).map(({ label, value, icon: Icon }) => <div key={label} className="card-surface flex items-center gap-3 p-4"><span className="icon-badge !size-10"><Icon className="size-5" /></span><div><p className="text-xs text-muted">{label}</p><p className="text-xl font-extrabold">{value}</p></div></div>)}</div><div className="mb-4 flex flex-wrap gap-2">{[["All Products", "/vendor/inventory"], ["Low Stock", "/vendor/inventory/low-stock"], ["Stock History", "/vendor/inventory/history"]].map(([label, to]) => <a key={to} href={to} className="btn-outline min-h-9 px-4 text-sm">{label}</a>)}</div></>}<section className="card-surface overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="bg-canvas text-xs text-muted"><tr>{["Product", "Category", "Price", "Available", "Reserved", "Status", "Actions"].map((h) => <th key={h} className="px-4 py-3 font-semibold">{h}</th>)}</tr></thead><tbody>{products.map((item) => <tr key={item.id} className="border-t border-line-soft"><td className="px-4 py-3"><div className="flex items-center gap-3"><img src={item.image} alt="" className="size-11 rounded-lg bg-mist object-cover" /><div><p className="font-semibold">{item.name}</p><p className="text-xs text-muted">{item.description}</p></div></div></td><td className="px-4 py-3 text-muted">{item.category}</td><td className="px-4 py-3 font-semibold tabular-nums">{formatINR(item.selling_price_paise)}</td><td className="px-4 py-3"><div className="inline-flex items-center overflow-hidden rounded-md border border-line"><button type="button" aria-label={`Decrease ${item.name} stock`} disabled={busy === item.id || item.available_quantity === 0} className="px-2 py-1 hover:bg-canvas disabled:opacity-40" onClick={() => void stock(item.id, -1)}>−</button><span className="min-w-9 text-center tabular-nums">{item.available_quantity}</span><button type="button" aria-label={`Increase ${item.name} stock`} disabled={busy === item.id} className="px-2 py-1 hover:bg-canvas" onClick={() => void stock(item.id, 1)}>+</button></div></td><td className="px-4 py-3 tabular-nums">{item.reserved_quantity}</td><td className="px-4 py-3"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${!item.enabled ? "bg-mist text-muted" : item.available_quantity === 0 ? "bg-red-50 text-red-700" : item.available_quantity <= item.minimum_stock ? "bg-amber-50 text-amber-800" : "bg-emerald-50 text-emerald-800"}`}>{!item.enabled ? "Hidden" : item.available_quantity === 0 ? "Out of stock" : item.available_quantity <= item.minimum_stock ? "Low stock" : "In stock"}</span></td><td className="px-4 py-3"><button type="button" disabled={busy === item.id} className="text-xs font-semibold text-primary hover:underline" onClick={() => void toggle(item)}>{item.enabled ? "Disable" : "Enable"}</button></td></tr>)}</tbody></table></div>{products.length === 0 && <p className="p-10 text-center text-sm text-muted">{lowStock ? "No low-stock items." : "No products in your shop yet. Add an item from the PrintHub catalog."}</p>}</section><div className="mt-5"><VendorNotice>Vendor stock changes affect only this shop's listing. Customer checkout still uses the legacy global catalog until shop-scoped order integration is complete.</VendorNotice></div></>;
}
